 render(){const ctx=this.context;this.banner.hidden=!ctx;document.body.classList.toggle('facilitating',!!ctx);for(const id of ['change-display-name','open-workspace','download-workspace']){const b=document.getElementById(id);if(b)b.disabled=!!ctx;}this.a.testAccounts.manage.hidden=!!ctx||!this.manager;if(!ctx)return;this.banner.replaceChildren(fEl('strong',`Facilitating for ${this.a.actor?.name||ctx.name} · Signed in as ${this.operator.name}`),fEl('span','Changes stay unpublished until reviewed.'),fButton('Review contribution',()=>this.a.save()),fButton('Discard pending changes',async()=>{if(!this.pending()||!confirm('Discard the unpublished changes for this participant?'))return;await this.switchTo({...this.context},true).catch(e=>this.c.message(e.message));}),fButton('Drafts',()=>this.open()),fButton('Exit facilitation',()=>this.switchTo(null).catch(e=>this.c.message(e.message))));document.getElementById('account-display').textContent=this.operator.name;}
