  if(!this.context&&this.a.actor)this.operator={...this.a.actor};this.busy=true;this.a.loading=true;this.epoch++;this.context=context;this.operations.clear();clearTimeout(this.a.timer);clearTimeout(this.a.draftTimer);
  this.c.workspaceDirty=false;this.c.comparisonDirty=false;if(this.c.discussion)this.c.discussion.dirty=false;if(this.c.argument)this.c.argument.dirty=false;this.c.editor.discardDraft();this.c.library.definitions.dirty=false;this.a.actor=null;this.a.baseline.clear();this.a.revisions={};this.a.ownedKeys=[];
  document.body.classList.add('account-locked');this.c.argument?.reset();this.c.discussion?.close();this.c.workspace={schemaVersion:6,participants:[],maps:[],ideas:[],endorsements:[],comparisons:[],comparisonThreads:[],argumentNodes:[],argumentEdges:[],discussions:[],definitions:[]};this.c.ready=false;this.c.activeMapId=null;this.c.activeComparisonPair=null;this.c.discussion.items=[];this.c.discussion.reasoning?.reset();this.c.participation.pending=null;this.c.participation.mapId=null;this.c.participation.podMapId=null;this.c.participation.nodeSet.clear();for(const canvas of [this.c.canvas,this.c.participation.canvas,this.c.participation.podCanvas])canvas.setMaps({a:{map:null},b:{map:null}});for(const dialog of document.querySelectorAll('dialog[open]')){dialog.close();if(dialog.classList.contains('facilitator-dialog'))dialog.remove();}
  try{this.a.accept(await this.a.request('/api/workspace'),true);this.a.blocked=false;const own=this.c.workspace.maps.find(m=>m.ownerId===this.a.actor.id);if(own){this.c.loadMap(own.id);this.c.activeMapId=null;}this.render();this.c.library.open('maps');if(recovery){const d=this.dialog('Unsaved facilitator wording');d.append(fEl('p','Permission ended before this wording was recorded. It has not been published. Copy it here if needed.'),fEl('pre',recovery));}return true;}catch(e){this.c.message(e.message);if(context){this.context=null;this.epoch++;try{this.a.accept(await this.a.request('/api/workspace'),true);this.render();}catch{}}throw e;}finally{this.busy=false;this.a.loading=false;this.a.status();}
